        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and (rr,cc) not in seen:
                seen.add((rr,cc)); q.append((rr,cc))
    return [[3 if v==0 and (r,c) not in seen else v for c,v in enumerate(row)] for r,row in enumerate(grid)]
'''
